/**
 * FloraError request ids.
 *
 * - `requestId` reads `Flora-Request-Id`, the header the API sets on every
 *   response. `src/generated` is regenerated by Fern, which hardcodes
 *   `x-request-id`; this fails if a regeneration brings that back.
 */
import { expect, test } from "vitest"

import { FloraClient, FloraError } from "../index.js"

test("an API error exposes the Flora-Request-Id response header as requestId", async () => {
  const client = new FloraClient({
    apiKey: "ak_test",
    baseUrl: "https://api.flora.test",
    maxRetries: 0,
    fetch: async () =>
      new Response(JSON.stringify({ error: { code: "not_found", message: "No such project." } }), {
        status: 404,
        headers: {
          "content-type": "application/json",
          "Flora-Request-Id": "0199e3a0-0000-7000-8000-000000000001",
        },
      }),
  })

  const error = await client.projects
    .retrieve({ projectId: "prj_missing" })
    .catch((caught: unknown) => caught)

  expect(error).toBeInstanceOf(FloraError)
  expect((error as FloraError).requestId).toBe("0199e3a0-0000-7000-8000-000000000001")
})
